def parse_json(json_str):
    def parse_value(json_str, index):
        if json_str[index] == '{':
            return parse_object(json_str, index + 1)
        elif json_str[index] == '[':
            return parse_list(json_str, index + 1)
        elif json_str[index] in '0123456789':
            return parse_number(json_str, index)
        elif json_str[index] in '"\'':
            return parse_string(json_str, index)
        elif json_str[index] == 't':
            return parse_true(json_str, index)
        elif json_str[index] == 'f':
            return parse_false(json_str, index)
        elif json_str[index] == 'n':
            return parse_null(json_str, index)
        else:
            raise ValueError(f"Invalid character at index {index}")

    def parse_object(json_str, index):
        obj = {}
        while json_str[index] != '}':
            key, value = parse_key_value(json_str, index)
            obj[key] = value
            index = skip_whitespace(json_str, index + 1)
            if json_str[index] == ',':
                index = skip_whitespace(json_str, index + 1)
        return obj

    def parse_key_value(json_str, index):
        key = parse_string(json_str, index)
        index = skip_whitespace(json_str, index + len(key))
        if json_str[index] != ':':
            raise ValueError(f"Missing colon after key at index {index}")
        index = skip_whitespace(json_str, index + 1)
        value = parse_value(json_str, index)
        return key, value

    def parse_list(json_str, index):
        lst = []
        while json_str[index] != ']':
            value = parse_value(json_str, index)
            lst.append(value)
            index = skip_whitespace(json_str, index + 1)
            if json_str[index] == ',':
                index = skip_whitespace(json_str, index + 1)
        return lst

    def parse_number(json_str, index):
        start = index
        if json_str[start] == '-':
            start += 1
        while index < len(json_str) and json_str[index].isdigit():
            index += 1
        if index < len(json_str) and json_str[index] in '.eE':
            index += 1
            if index < len(json_str) and (json_str[index] == '-' or json_str[index].isdigit()):
                index += 1
        return int(json_str[start:index]) if '.' not in json_str[start:index] else float(json_str[start:index])

    def parse_string(json_str, index):
        start = index
        while index < len(json_str) and json_str[index] != '"' and json_str[index] != '\'':
            index += 1
        if json_str[start] == '"' and json_str[index] == '"':
            raise ValueError(f"Invalid escaped double quote at index {index}")
        elif json_str[start] == '\'' and json_str[index] == '\'':
            raise ValueError(f"Invalid escaped single quote at index {index}")
        return json_str[start:index]

    def parse_true(json_str, index):
        if json_str[index:index + 4] == 'true':
            return True
        raise ValueError(f"Invalid token 'true' at index {index}")

    def parse_false(json_str, index):
        if json_str[index:index + 5] == 'false':
            return False
        raise ValueError(f"Invalid token 'false' at index {index}")

    def parse_null(json_str, index):
        if json_str[index:index + 4] == 'null':
            return None
        raise ValueError(f"Invalid token 'null' at index {index}")

    def skip_whitespace(json_str, index):
        while index < len(json_str) and json_str[index].isspace():
            index += 1
        return index

    return parse_value(json_str, 0)

def parse_json(json_str):
    def parse_value(tokens):
        if not tokens:
            raise ValueError("Unexpected end of input")
        token = tokens[0]
        tokens = tokens[1:]

        if token == '[':
            if tokens[0] == ']':
                return []
            result = [parse_value(tokens)]
            while tokens and tokens[0] != ']':
                tokens = tokens[1:]
                if tokens[0] != ',':
                    raise ValueError("Expected comma after value")
                tokens = tokens[1:]
                result.append(parse_value(tokens))
            tokens = tokens[1:]  # Consume ']'
            return result
        elif token == '{':
            if tokens[0] == '}':
                return {}
            result = {tokens[0]: parse_value(tokens[2:])}
            while tokens and tokens[0] != '}':
                tokens = tokens[1:]
                if tokens[0] != ',':
                    raise ValueError("Expected comma after key-value pair")
                tokens = tokens[1:]
                if tokens[0] != ':':
                    raise ValueError("Expected colon after key")
                tokens = tokens[1:]
                result[tokens[0]] = parse_value(tokens[2:])
            tokens = tokens[1:]  # Consume '}'
            return result
        elif token in ('true', 'false'):
            return token == 'true'
        elif token.isdigit():
            return int(token)
        elif token == '.':
            if not tokens or not tokens[0].isdigit():
                raise ValueError("Invalid number format")
            number = token
            while tokens and tokens[0].isdigit():
                number += tokens[0]
                tokens = tokens[1:]
            if tokens and tokens[0] == 'e' or tokens[0] == 'E':
                number += tokens[0]
                tokens = tokens[1:]
                if tokens and tokens[0] in ('+', '-'):
                    number += tokens[0]
                    tokens = tokens[1:]
                if not tokens or not tokens[0].isdigit():
                    raise ValueError("Invalid number format")
                while tokens and tokens[0].isdigit():
                    number += tokens[0]
                    tokens = tokens[1:]
            return float(number)
        elif token == 'null':
            return None
        else:
            raise ValueError(f"Unexpected token: {token}")

    tokens = iter(json_str.replace(" ", ""))
    return parse_value(tokens)

def parse_json(json_str):
    def parse_array():
        result = []
        i = 1  # Skip the opening bracket '['
        while i < len(json_str):
            if json_str[i] == ']':
                return result
            elif json_str[i] == ',':  # Separate elements by commas
                i += 1
            elif json_str[i] == '{':  # Nested array
                result.append(parse_object())
            elif json_str[i] == '[':  # Nested array
                result.append(parse_array())
            elif json_str[i].isdigit() or json_str[i] in '+-':  # Integer or float
                j = i
                while j < len(json_str) and (json_str[j].isdigit() or json_str[j] in '+-'):
                    j += 1
                result.append(int(json_str[i:j])) if json_str[i] not in '+-' else float(json_str[i:j])
                i = j - 1
            elif json_str[i].isalpha():  # String
                j = i
                while j < len(json_str) and json_str[j] != ',' and json_str[j] != ']' and json_str[j] != '{' and json_str[j] != '[':
                    j += 1
                result.append(json_str[i:j])
                i = j - 1
            elif json_str[i] in 'tnf':  # Boolean
                if json_str[i:i+2] in ['tr', 'fa']:
                    result.append(True)
                elif json_str[i:i+2] in ['fl', 'al']:
                    result.append(False)
                i += 1
            elif json_str[i] == 'n':  # Null
                result.append(None)
                i += 2  # Skip 'null'
            else:
                raise ValueError(f"Unexpected character '{json_str[i]}' at position {i}")
            i += 1
        raise ValueError("Unterminated array")

    def parse_object():
        result = {}
        i = 1  # Skip the opening brace '{'
        while i < len(json_str):
            if json_str[i] == '}':
                return result
            elif json_str[i] == ',':  # Separate key-value pairs by commas
                i += 1
            elif json_str[i] == '{':  # Nested object
                result[parse_string()] = parse_object()
            elif json_str[i] == '[':  # Nested array
                result[parse_string()] = parse_array()
            elif json_str[i].isdigit() or json_str[i] in '+-':  # Integer or float
                j = i
                while j < len(json_str) and (json_str[j].isdigit() or json_str[j] in '+-'):
                    j += 1
                result[parse_string()] = int(json_str[i:j]) if json_str[i] not in '+-' else float(json_str[i:j])
                i = j - 1
            elif json_str[i].isalpha():  # String
                j = i
                while j < len(json_str) and json_str[j] != ',' and json_str[j] != '}' and json_str[j] != '{' and json_str[j] != '[':
                    j += 1
                result[parse_string()] = json_str[i:j]
                i = j - 1
            elif json_str[i] in 'tnf':  # Boolean
                if json_str[i:i+2] in ['tr', 'fa']:
                    result[parse_string()] = True
                elif json_str[i:i+2] in ['fl', 'al']:
                    result[parse_string()] = False
                i += 1
            elif json_str[i] == 'n':  # Null
                result[parse_string()] = None
                i += 2  # Skip 'null'
            else:
                raise ValueError(f"Unexpected character '{json_str[i]}' at position {i}")
            i += 1
        raise ValueError("Unterminated object")

    def parse_string():
        result = ''
        i = 1
        while i < len(json_str):
            if json_str[i] == '"':
                return result
            elif json_str[i] == '\\':
                i += 1  # Skip the backslash
                if json_str[i] == 'n':
                    result += '\n'
                elif json_str[i] == 't':
                    result += '\t'
                elif json_str[i] == 'r':
                    result += '\r'
                elif json_str[i] == '"':
                    result += '"'
                elif json_str[i] == '\\':
                    result += '\\'
                elif json_str[i] == 'u':  # Unicode escape
                    j = i + 5
                    while j < len(json_str) and json_str[j].isalnum():
                        j += 1
                    unicode_value = int(json_str[i+1:j], 16)
                    result += chr(unicode_value)
                    i = j - 1
                else:
                    raise ValueError(f"Invalid escape sequence '\\{json_str[i]}' at position {i}")
            else:
                result += json_str[i]
            i += 1
        raise ValueError("Unterminated string")

    if json_str[0] == '[':
        return parse_array()
    elif json_str[0] == '{':
        return parse_object()
    elif json_str[0].isdigit() or json_str[0] in '+-':  # Integer or float
        j = 1
        while j < len(json_str) and (json_str[j].isdigit() or json_str[j] in '+-'):
            j += 1
        return int(json_str[0:j]) if json_str[0] not in '+-' else float(json_str[0:j])
    elif json_str[0].isalpha():  # String
        j = 1
        while j < len(json_str) and json_str[j] != ',' and json_str[j] != '}' and json_str[j] != '{' and json_str[j] != '[':
            j += 1
        return json_str[0:j]
    elif json_str[0] in 'tnf':  # Boolean
        if json_str[0:2] in ['tr', 'fa']:
            return True
        elif json_str[0:2] in ['fl', 'al']:
            return False
    elif json_str[0] == 'n':  # Null
        return None
    else:
        raise ValueError(f"Invalid JSON string at position 0")
